{
  "technical_and_design_decisions": [
    "Target the existing Spring XD distributed runtime architecture (XD-Admin server, XD-Container servers, pluggable message bus, stream/job modules) and implement all changes within the current Java/Spring codebase.",
    "U2 (lazy job bootstrapping): introduce an on-demand deployment path for job modules in the container, triggered by job launch requests from the admin server; use job execution lifecycle listeners to shut down and release the module's ApplicationContext after job completion, instead of bootstrapping at module deployment time.",
    "U4 (metrics): embed Spring Boot actuator's MetricRepository/export mechanism into module contexts so module/app-specific counters and gauges are exported through the existing XD metrics backend rather than a custom metrics API.",
    "U5 (module options): replace XD-runtime-managed module option metadata with Boot property source management and Boot configuration metadata (generated via the configuration processor), so module options are injected as Boot properties.",
    "U6 (externalized configuration): adopt a centralized configuration-server approach (Spring Cloud Config style) with client-side property resolution in XD-Admin and XD-Container at startup, supporting per-environment property sources.",
    "U7 (Rabbit bus): reuse the benchmark harness produced for U1 to profile the Rabbit message bus (prefetch, concurrency, ack modes, serialization) and apply targeted configuration/code fixes.",
    "U8 (CI migration): migrate MASTER branch CI to Jenkins agents running on EC2 using pre-baked AMIs, with centralized credentials and build-job definitions.",
    "U1 (benchmarks): define a repeatable benchmark suite (stream throughput, job throughput, latency) executed on a documented reference EC2 cluster topology, with results published in the project reference documentation."
  ],
  "assumptions": [
    "A single developer performs all work sequentially; estimates express total effort in workdays (8 hours per workday), not elapsed calendar time.",
    "The existing Spring XD codebase, test suites, and build system are available and build cleanly at the start; the developer has working familiarity with the codebase, so no extended ramp-up activity is needed.",
    "Access to an AWS EC2 account for benchmarks and CI migration, and to a RabbitMQ cluster for message bus troubleshooting, is available at no additional setup cost beyond the listed activities.",
    "No new UI features are required; any REST API surface changes are minor and included within the relevant activity estimates.",
    "Documentation deliverables are published through the existing Asciidoc-based reference documentation and examples repository.",
    "Existing unit/integration test infrastructure is reusable; effort for writing new tests is included within each development activity.",
    "Fixes required by U7 are limited to configuration tuning and localized code changes in the Rabbit bus implementation, not a redesign of the message bus SPI."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and technical design",
      "activity_description": "Analyze the eight user stories, produce the overall design for lazy job module lifecycle, actuator-based metrics export, Boot-based module option handling, externalized configuration for XD-Admin/XD-Container, benchmark approach, Rabbit bus profiling plan, and EC2 CI migration plan; document design decisions and review them.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Performance benchmark suite and publication",
      "activity_description": "Define benchmark scenarios for streams and jobs, provision and document the reference cluster infrastructure on EC2, implement/run the benchmark harness, collect results, and publish benchmarks together with infrastructure specifics in the project documentation.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A3",
      "activity_name": "U2 - Lazy job module bootstrapping",
      "activity_description": "Refactor container module deployment so job modules are bootstrapped on job launch and shut down on job completion; implement lifecycle coordination with the admin server, context/resource cleanup on completion, and unit plus integration tests verifying resource utilization behavior.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A4",
      "activity_name": "U3 - Spark streaming documentation and examples update",
      "activity_description": "Update Spark streaming documentation to cover tapping at the Spark module output, refresh the related examples, and add a section explaining the Reliable receiver semantics and configuration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "U4 - Module metrics via Boot actuator export",
      "activity_description": "Integrate Boot actuator MetricRepository export into module contexts so module/app-specific metrics are consumed directly from the export API; wire exported metrics to the XD metrics backend and add tests covering counters, gauges, and export behavior.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6",
      "activity_name": "U5 - Module options via Boot property source management",
      "activity_description": "Refactor module option resolution to pure Boot property source management, generate and consume Boot configuration metadata for module options, adapt module option injection accordingly, and update tests and affected modules.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A7",
      "activity_name": "U6 - Externalized configuration for XD-Admin and XD-Container",
      "activity_description": "Implement a central configuration service for managing external properties across environments and add server-side and client-side support so XD-Admin and XD-Container resolve their configuration from it at startup; include handling of environment selection and sensitive properties, plus tests.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "U7 - Rabbit message bus performance troubleshooting and fixes",
      "activity_description": "Profile the Rabbit message bus implementation using the benchmark harness, isolate bottlenecks (prefetch, concurrency, acknowledgement, serialization), implement and tune the appropriate fixes, and re-run benchmarks to verify the improvement.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "U8 - Migrate MASTER branch CI builds to EC2",
      "activity_description": "Provision EC2-based CI build agents (AMI preparation, tooling, credentials), migrate all MASTER branch CI jobs to the new infrastructure, and validate build reliability and parity with the previous environment.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration, regression testing and release preparation",
      "activity_description": "Run end-to-end integration and regression testing across all changes (module lifecycle, metrics, configuration, message bus), fix integration defects, finalize documentation and release notes for the increment.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 84
  }
}

